/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: installMediaCardHome
 *   Constants: albumPlayName, trackCardHome
 * Tests
 *   - Album card Play stays hidden at rest, appears on keyboard focus, and starts the Album without leaving Home
 *   - Album card Play is revealed by hover and remains visible in forced colors
 *   - the playing MediaTrack card keeps a Pause control and an accent title until paused
 *   - a mouse resting on a Video card plays a muted preview without touching the shared player
 *   - with motion previews enabled, a Video card plays its dedicated clip instead of the stream
 *   - with a touch pointer
 *     - Album cards open the Album and offer no separate card Play
 * @end-catalog */

import type { Page } from '@playwright/test';

import type { ListenerHome } from '../src/api/contentSchemas';

import { albumFixture, trackFixtures } from './fixtures/catalog';
import { installDeterministicAudio } from './support/deterministicAudio';
import { expect, test } from './support/test';

const albumPlayName = 'Play album Quiet Hours by Finitude Ensemble';

const trackCardHome = {
  title: 'Media card room',
  sections: [
    { id: 'media-card-albums', title: 'Albums to start', presentation: 'carousel', items: [albumFixture] },
    // First Light is a Video MediaTrack, so its card offers the hover preview.
    { id: 'media-card-tracks', title: 'MediaTracks to start', presentation: 'carousel', items: [trackFixtures[1], trackFixtures[0]] }
  ]
} satisfies ListenerHome;

/** Serves a Home with Album and audio MediaTrack cards so both card actions are reachable. */
const installMediaCardHome = async (page: Page) => {
  await page.route('**/api/listener/v1/home', (route) => route.fulfill({
    status: 200,
    contentType: 'application/json; charset=utf-8',
    headers: { 'Cache-Control': 'no-store' },
    body: JSON.stringify(trackCardHome)
  }));
};

test('Album card Play stays hidden at rest, appears on keyboard focus, and starts the Album without leaving Home', async ({ page }) => {
  await installDeterministicAudio(page);
  await installMediaCardHome(page);
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.goto('/finitude');

  const main = page.getByRole('main');
  const albumLink = main.getByRole('link', { name: 'Quiet Hours, album' });
  const albumPlay = main.getByRole('button', { name: albumPlayName });
  await expect(albumLink).toBeVisible();
  await page.mouse.move(0, 0);
  await expect(albumPlay).toHaveCSS('opacity', '0');

  await albumLink.focus();
  await page.keyboard.press('Tab');
  await expect(albumPlay).toBeFocused();
  await expect(albumPlay).toHaveCSS('opacity', '1');

  await page.keyboard.press('Enter');
  const player = page.getByRole('region', { name: 'Now playing' });
  await expect(player.getByText('First Light', { exact: true })).toBeVisible();
  await expect(page).toHaveURL(/\/finitude\/?$/);
});

test('Album card Play is revealed by hover and remains visible in forced colors', async ({ page }) => {
  await installMediaCardHome(page);
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.goto('/finitude');

  const main = page.getByRole('main');
  const albumPlay = main.getByRole('button', { name: albumPlayName });
  await main.getByRole('link', { name: 'Quiet Hours, album' }).hover();
  await expect(albumPlay).toHaveCSS('opacity', '1');

  // Settle the at-rest state first so the forced-colors check cannot pass mid-fade.
  await page.mouse.move(0, 0);
  await expect(albumPlay).toHaveCSS('opacity', '0');
  await page.emulateMedia({ forcedColors: 'active' });
  await expect(albumPlay).toHaveCSS('opacity', '1');
});

test('the playing MediaTrack card keeps a Pause control and an accent title until paused', async ({ page }) => {
  await installDeterministicAudio(page);
  await installMediaCardHome(page);
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude');

  const main = page.getByRole('main');
  await main.getByRole('button', { name: 'Play Night Window by Finitude Ensemble' }).click();
  const pauseCard = main.getByRole('button', { name: 'Pause Night Window' });
  await expect(pauseCard).toHaveAttribute('aria-current', 'true');
  await page.mouse.move(0, 0);
  await pauseCard.evaluate((element) => (element as HTMLElement).blur());
  // Without transitions the at-rest opacity is immediate: hidden for idle cards, shown while playing.
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await expect(pauseCard.getByText('Night Window', { exact: true })).toHaveCSS('color', 'rgb(30, 215, 96)');
  await expect(pauseCard.locator('svg.lucide-pause').locator('..')).toHaveCSS('opacity', '1');
  await expect(main.getByRole('button', { name: albumPlayName })).toHaveCSS('opacity', '0');

  await pauseCard.click();
  await expect(main.getByRole('button', { name: 'Play Night Window by Finitude Ensemble' })).toBeVisible();
  await expect(main.getByRole('button', { name: 'Pause Night Window' })).toHaveCount(0);
});

test('a mouse resting on a Video card plays a muted preview without touching the shared player', async ({ page }) => {
  await installMediaCardHome(page);
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude');

  const main = page.getByRole('main');
  const videoCard = main.locator('article').filter({
    has: page.getByRole('button', { name: 'Play First Light by Finitude Ensemble' })
  });
  await videoCard.hover();
  const preview = videoCard.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  await expect(preview).toHaveAttribute('aria-hidden', 'true');
  expect(await preview.evaluate((video) => {
    const media = video as HTMLVideoElement;
    return { muted: media.muted, paused: media.paused, path: new URL(media.src).pathname };
  })).toEqual({ muted: true, paused: false, path: '/content/mediaTrack/stream/e2e-first-light' });

  // The preview is decoration: the shared player keeps no queue and shows nothing playing.
  await expect(page.getByRole('region', { name: 'Now playing' }).getByText('Nothing playing')).toBeVisible();

  await page.mouse.move(0, 0);
  await expect(preview).toHaveCount(0);

  await page.emulateMedia({ reducedMotion: 'reduce' });
  await videoCard.hover();
  await page.waitForTimeout(900);
  await expect(videoCard.locator('video[data-video-preview]')).toHaveCount(0);
});

test('with motion previews enabled, a Video card plays its dedicated clip instead of the stream', async ({ api, page }) => {
  await installMediaCardHome(page);
  await page.route('**/api/listener/v1/presentation-capabilities', (route) => route.fulfill({
    status: 200, contentType: 'application/json', body: JSON.stringify({ contractVersion: 1, motionPreviews: true })
  }));
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude');

  const videoCard = page.getByRole('main').locator('article').filter({
    has: page.getByRole('button', { name: 'Play First Light by Finitude Ensemble' })
  });
  await videoCard.hover();
  const preview = videoCard.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate((video) => new URL((video as HTMLVideoElement).src).pathname))
    .toBe('/content/mediaTrack/motion-preview/e2e-first-light');
  expect(api.calls.filter((call) => call.pathname === '/content/mediaTrack/stream/e2e-first-light')).toHaveLength(0);
});

test.describe('with a touch pointer', () => {
  test.use({ hasTouch: true });

  test('Album cards open the Album and offer no separate card Play', async ({ page }) => {
    await installMediaCardHome(page);
    await page.setViewportSize({ width: 1_280, height: 800 });
    await page.goto('/finitude');

    const main = page.getByRole('main');
    await expect(main.getByRole('link', { name: 'Quiet Hours, album' })).toBeVisible();
    await expect(main.getByRole('button', { name: albumPlayName })).toBeHidden();
  });
});
